package dev.zomboid.cleanup;import java.util.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.entity.monster.Zombie;
public class Checks {
 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
 public static class Tag {Map<String,Object> data=new HashMap<>();public boolean getBoolean(String k){return Boolean.TRUE.equals(data.get(k));}public boolean hasUUID(String k){return data.get(k) instanceof UUID;}public Object getUUID(String k){return data.get(k);}public boolean contains(String k){return data.containsKey(k);}public long getLong(String k){return ((Number)data.getOrDefault(k,0L)).longValue();}public void putLong(String k,long v){data.put(k,v);}}
 public static class World {public boolean isClientSide;public long time;public List<Base> players=new ArrayList<>();public List<Base> players(){return players;}public long getGameTime(){return time;}}
 public static class Stack {public boolean named;public boolean has(Object c){return named;}}
 public static class Base {public int tickCount=100;public int id;public boolean removed,named,persistent,passenger,vehicle,alive=true,spectator;public double x;public World world=new World();public Tag tag=new Tag();public Base target;public boolean hasCustomName(){return named;}public boolean isRemoved(){return removed;}public void discard(){removed=true;}public int getId(){return id;}public World level(){return world;}public Tag getPersistentData(){return tag;}public boolean isPersistenceRequired(){return persistent;}public boolean isPassenger(){return passenger;}public boolean isVehicle(){return vehicle;}public Base getTarget(){return target;}public boolean isAlive(){return alive;}public boolean isSpectator(){return spectator;}public double distanceToSqr(Base other){return (x-other.x)*(x-other.x);}}
 public record Event(Base entity){public Base getEntity(){return entity;}}
 static final Cleanup.Settings S=new Cleanup.Settings(true,true,2400,6000,16,64,8);
 static Zombie horde(){Zombie z=new Zombie();z.tag.data.put("zh_spawned",true);return z;}
 public static void main(String[]args){ItemEntity item=new ItemEntity();item.age=2399;check(!Cleanup.eligible(item,item.world,0,true,S),"fresh loot");item.age=2400;check(Cleanup.eligible(item,item.world,0,true,S),"old distant loot");Base player=new Base();item.world.players.add(player);check(!Cleanup.eligible(item,item.world,0,true,S),"near player");player.x=17;check(Cleanup.eligible(item,item.world,0,true,S),"outside protection");item.stack.named=true;check(!Cleanup.eligible(item,item.world,0,true,S),"named stack");item.stack.named=false;item.named=true;check(!Cleanup.eligible(item,item.world,0,true,S),"named entity");Zombie z=horde();check(!Cleanup.eligible(z,z.world,100,false,S),"initial observation");check(!Cleanup.eligible(z,z.world,6099,false,S),"not old enough");check(Cleanup.eligible(z,z.world,6100,false,S),"abandoned horde");z.tag.data.put("zh_population",true);check(!Cleanup.eligible(z,z.world,6100,false,S),"population unchanged");z.tag.data.remove("zh_population");z.tag.data.put("FactionPveWave","active");check(!Cleanup.eligible(z,z.world,6100,false,S),"faction wave protected");z.tag.data.remove("FactionPveWave");z.persistent=true;check(!Cleanup.eligible(z,z.world,6100,false,S),"persistent zombie");z.persistent=false;z.target=new Base();check(!Cleanup.eligible(z,z.world,6100,false,S),"combat protected");z.target=null;check(!Cleanup.eligible(z,z.world,12099,false,S),"combat resets inactivity");check(Cleanup.eligible(z,z.world,12100,false,S),"idle expires again");z.tag.putLong("zh_until",15000);check(!Cleanup.eligible(z,z.world,12100,false,S),"noise memory protected");z.tag.putLong("zh_until",0);z.world.players.add(player);player.x=60;check(!Cleanup.eligible(z,z.world,13000,false,S),"nearby player resets timer");z.world.players.clear();check(!Cleanup.eligible(z,z.world,100,false,S),"time rollback safe");Zombie ordinary=new Zombie();check(!Cleanup.eligible(ordinary,ordinary.world,20000,false,S),"unmarked zombie protected");z.passenger=true;check(!Cleanup.eligible(z,z.world,20000,false,S),"passenger protected");z.passenger=false;z.vehicle=true;check(!Cleanup.eligible(z,z.world,20000,false,S),"vehicle protected");World w=new World();List<ItemEntity> litter=new ArrayList<>();for(int i=0;i<10;i++){ItemEntity e=new ItemEntity();e.age=2400;e.world=w;litter.add(e);Cleanup.tick(new Event(e));}check(litter.stream().filter(e->e.removed).count()==8,"bounded removal budget");w.time=20;for(ItemEntity e:litter)Cleanup.tick(new Event(e));check(litter.stream().filter(e->e.removed).count()==10,"budget resumes");ItemEntity client=new ItemEntity();client.age=5000;client.world.isClientSide=true;Cleanup.tick(new Event(client));check(!client.removed,"server only");ItemEntity stagger=new ItemEntity();stagger.age=5000;stagger.id=1;Cleanup.tick(new Event(stagger));check(!stagger.removed,"checks staggered");Zombie ticketZombie=horde();UUID ticketId=UUID.randomUUID();ticketZombie.tag.data.put("zh_ticket",ticketId);ticketZombie.tag.putLong("zh_cleanup_idle_since",0);dev.zomboid.hordes.HordeData.INSTANCE.tickets.add(new dev.zomboid.hordes.HordeData.Ticket(ticketId));check(!Cleanup.eligible(ticketZombie,ticketZombie.world,10000,false,S),"active ticket protected");dev.zomboid.hordes.HordeData.INSTANCE.tickets.clear();check(Cleanup.eligible(ticketZombie,ticketZombie.world,16000,false,S),"expired ticket may clean after inactivity");Properties props=new Properties();props.setProperty("item-age-seconds","bad");check(Cleanup.Settings.number(props,"item-age-seconds",120,30,3600)==120,"bad config falls back");props.setProperty("item-age-seconds","0");check(Cleanup.Settings.number(props,"item-age-seconds",120,30,3600)==30,"config minimum protects fresh loot");System.out.println("Cleanup safety, expiry, combat, faction and per-second budget checks: "+checks);}
}
